// 1. Read all items, build a Map of minimal objects & collect all subtask IDs
const items = $input.all();
const lookup = new Map();
const allSubtaskIds = new Set();

for (const { json: orig } of items) {
  const p = orig.properties || {};
  const id = orig.id;

  // Gather this page’s subtask IDs
  const subIds = (p["Sub-tasks"]?.relation || []).map(r => r.id);
  subIds.forEach(allSubtaskIds.add, allSubtaskIds);

  // Store minimal object in the map, include an empty subtasks array
  lookup.set(id, {
    page_id:            id,
    subIds,                                        // temp list for attachment
    manager_id:         p.Manager?.people?.[0]?.id ?? null,
    manager_name:       p.Manager?.people?.[0]?.name ?? null,
    manager_hours:      p["Manager Hours"]?.number ?? null,   // ← captured here
    created_by_id:      p["Created by"]?.created_by?.id    ?? null,
    created_by_name:    p["Created by"]?.created_by?.name  ?? null,
    hours_estimated:    p["Hours Est."]?.number            ?? null,
    hours_actual:       p["Hours Act."]?.number            ?? null,
    client_formatted:   p["Client Formatted"]?.formula?.string ?? null,
    type_labels:        (p.Type?.multi_select || []).map(ms => ms.name),
    task_name:          p["Task name"]?.title?.[0]?.plain_text ?? null,
    status:             p.Status?.status?.name             ?? null,
    time_diff:          p["Time Diff"]?.formula?.number    ?? null,
    remaining_hours:    p["Remaining Hours"]?.formula?.number ?? null,
    maker_id:           p.Maker?.people?.[0]?.id           ?? null,
    maker_name:         p.Maker?.people?.[0]?.name         ?? null,
    url:                orig.url                           ?? null,
    subtasks: []                                  // will fill below
  });
}

// 2. Attach subtasks in one pass over the map
for (const obj of lookup.values()) {
  for (const sid of obj.subIds) {
    const child = lookup.get(sid);
    if (child) obj.subtasks.push(child);
  }
  delete obj.subIds; // clean up temp field
}

// 3. Filter out only top-level tasks and shape final output
return Array.from(lookup.values())
  .filter(o => !allSubtaskIds.has(o.page_id))
  .map(o => ({
    json: {
      task_id:               o.page_id,
      task_manager_id:       o.manager_id,
      task_manager_name:     o.manager_name,
      task_manager_hours:    o.manager_hours,   // ← emitted here
      task_created_by_id:    o.created_by_id,
      task_created_by_name:  o.created_by_name,
      task_hours_estimated:  o.hours_estimated,
      task_hours_actual:     o.hours_actual,
      task_client:           o.client_formatted,
      task_types:            o.type_labels.length
                                ? o.type_labels.join(', ')
                                : null,
      task_name:             o.task_name,
      task_status:           o.status,
      task_time_diff:        o.time_diff,
      task_remaining_hours:  o.remaining_hours,
      task_maker_id:         o.maker_id,
      task_maker_name:       o.maker_name,
      task_url:              o.url,
      subtasks: o.subtasks.map(s => ({
        task_id:               s.page_id,
        task_manager_id:       s.manager_id,
        task_manager_name:     s.manager_name,
        task_manager_hours:    s.manager_hours,  // ← and here
        task_created_by_id:    s.created_by_id,
        task_created_by_name:  s.created_by_name,
        task_hours_estimated:  s.hours_estimated,
        task_hours_actual:     s.hours_actual,
        task_client:           s.client_formatted,
        task_types:            s.type_labels.length
                                  ? s.type_labels.join(', ')
                                  : null,
        task_name:             s.task_name,
        task_status:           s.status,
        task_time_diff:        s.time_diff,
        task_remaining_hours:  s.remaining_hours,
        task_maker_id:         s.maker_id,
        task_maker_name:       s.maker_name,
        task_url:              s.url
      }))
    }
  }));
